                return
            end
            ctx.CaptureKey = nil
            control:Refresh()
            if ctx.PopupAnchor == button then
                ctx:ClosePopup()
                return
            end
            local popup = ctx:OpenPopup(button, 132, 102)
            ctx:Padding(popup, 6)
            ctx:List(popup, 3)
            for _, mode in ipairs({ 'Hold', 'Toggle', 'Always' }) do
                local item = ctx:Button(mode, popup, { Size = UDim2.new(1, 0, 0, 28), ZIndex = 102 })
                ctx:Paint(item, control.Mode == mode and 'Hover' or 'Field')
                item.TextTransparency = control.Mode == mode and 0 or 0.3
                ctx:Connect(item.Activated, function()
                    control:SetMode(mode)
                    ctx:ClosePopup()
                end, ctx.PopupConnections)
            end
        end)
        if ctx.UpdateKeybinds then
            ctx.UpdateKeybinds()
        end
        return control
    end
    function section:AddToggle(id, options)
        return self:Toggle(aliasOptions(id, options))
    end
    function section:AddSlider(id, options)
        return self:Slider(aliasOptions(id, options))
    end
    function section:AddRangeSlider(id, options)
        return self:RangeSlider(aliasOptions(id, options))
    end
    function section:AddDropdown(id, options)
        return self:Dropdown(aliasOptions(id, options))
    end
    function section:AddInput(id, options)
        return self:Textbox(aliasOptions(id, options))
    end
    function section:AddButton(options, callback)
        if type(options) == 'string' then
            options = { Text = options, Callback = callback }
        end
        return self:Button(options)
    end
    function section:AddLabel(text)
        local frame = row(ctx, body, text)
        local label = frame:FindFirstChildWhichIsA('TextLabel')
        local owner = attachments({ Root = frame })
        function owner:SetText(value)
            label.Text = value
        end
        return owner
    end
    function section:AddDivider()
        local line = ctx:New('Frame', { Size = UDim2.new(1, 0, 0, 1) }, body)
        ctx:Paint(line, 'Border')
        return line
    end
    function section:ColorPicker(options)
        local frame = options._Host or row(ctx, body, options.Text or 'Color', 36, options.Description)
        local button = ctx:Button(
            '',
            frame,
            { Position = UDim2.new(1, -(options._Offset or 28), 0, 6), Size = UDim2.fromOffset(24, 24) }
        )
        button.BackgroundTransparency = 1
        for _, child in ipairs(button:GetChildren()) do
            child:Destroy()
        end
        local swatch = ctx:New('Frame', { Name = 'Swatch', Size = UDim2.fromScale(1, 1) }, button)
        ctx:New('UICorner', { CornerRadius = UDim.new(0, 4) }, swatch)
        local control = register(
            ctx,
            options,
            { Value = options.Default or ctx.Theme.Accent, ThemeRole = options.ThemeRole, Root = frame }
        )
        function control:Refresh()
            swatch.BackgroundColor3 = self.Value
        end
        function control:Set(value, silent)
            if typeof(value) ~= 'Color3' then
                return false
            end
            self.Value = value
            self:Refresh()
            if not silent then
                ctx:Callback(options.Callback, value)
            end
            return true
        end
        control:Refresh()
        ctx:Connect(button.Activated, function()
            if ctx.PopupAnchor == button then
                ctx:ClosePopup()
                return
            end
            local popup = ctx:OpenPopup(button, 242, 240)
            local hue, sat, val = control.Value:ToHSV()
            local square = ctx:New('Frame', {
                Position = UDim2.fromOffset(10, 10),
                Size = UDim2.new(1, -20, 0, 166),
                Active = true,
                ZIndex = 101,
            }, popup)
            local white = ctx:New(
                'Frame',
                { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 102 },
                square
            )
            ctx:New('UIGradient', { Transparency = NumberSequence.new(0, 1) }, white)
            local black = ctx:New(
                'Frame',
                { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), ZIndex = 103 },
                square
            )
            ctx:New('UIGradient', { Rotation = 90, Transparency = NumberSequence.new(1, 0) }, black)
            local cursor = ctx:New('Frame', {
                Size = UDim2.fromOffset(7, 7),
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = Color3.new(1, 1, 1),
                ZIndex = 104,
            }, square)
            ctx:Stroke(cursor)
            local strip = ctx:New('Frame', {
                Position = UDim2.fromOffset(10, 185),
                Size = UDim2.new(1, -20, 0, 16),
                BackgroundColor3 = Color3.new(1, 1, 1),
                Active = true,
                ZIndex = 101,
            }, popup)
            local colors = {}
            for i = 0, 6 do
                table.insert(colors, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(i / 6, 1, 1)))
            end
            ctx:New('UIGradient', { Color = ColorSequence.new(colors) }, strip)
            local hueMarker = ctx:New('Frame', {
                Size = UDim2.fromOffset(3, 20),
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundColor3 = Color3.new(1, 1, 1),
                ZIndex = 102,
            }, strip)
            local hex = ctx:New('TextBox', {
                Position = UDim2.fromOffset(10, 207),
                Size = UDim2.new(1, -20, 0, 25),
                BackgroundTransparency = 1,
                ClearTextOnFocus = false,
                ZIndex = 102,
            }, popup)
            local function refresh()
                square.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
                cursor.Position = UDim2.fromScale(sat, 1 - val)
                hueMarker.Position = UDim2.new(hue, 0, 0, -2)
                hex.Text = '#' .. control.Value:ToHex()
            end
            ctx:Pointer(square, function(pos)
                sat =
                    math.clamp((pos.X - square.AbsolutePosition.X) / math.max(1, square.AbsoluteSize.X), 0, 1)
                val = 1
                    - math.clamp(
                        (pos.Y - square.AbsolutePosition.Y) / math.max(1, square.AbsoluteSize.Y),
                        0,
                        1
                    )
                control:Set(Color3.fromHSV(hue, sat, val))
                refresh()
            end, nil, ctx.PopupConnections)
            ctx:Pointer(strip, function(pos)
                hue = math.clamp((pos.X - strip.AbsolutePosition.X) / math.max(1, strip.AbsoluteSize.X), 0, 1)
                control:Set(Color3.fromHSV(hue, sat, val))
                refresh()
            end, nil, ctx.PopupConnections)
            ctx:Connect(hex.FocusLost, function()
                local value = hex.Text:gsub('^#', '')
                if #value == 6 and value:match('^%x+$') then
                    control:Set(Color3.fromHex(value))
                    hue, sat, val = control.Value:ToHSV()
                end
                refresh()
            end, ctx.PopupConnections)
            refresh()
        end)
        return control
    end
    return section
end
return Components

end
factories['Storage'] = function()
local Storage = {}
function Storage.new(folder, backend)
    backend = backend
        or {
            readfile = readfile,
            writefile = writefile,
            isfile = isfile,
            isfolder = isfolder,
            makefolder = makefolder,
            listfiles = listfiles,
            delfile = delfile,
        }
    assert(
        type(folder) == 'string'
            and #folder > 0
            and not folder:find('%.%.')
            and not folder:find('[:%c]')
            and not folder:match('^[/\\]'),
        'Invalid storage folder'
    )
    folder = folder:gsub('\\', '/'):gsub('/+$', '')
    local disk = type(backend.readfile) == 'function'
        and type(backend.writefile) == 'function'
        and type(backend.isfile) == 'function'
        and type(backend.isfolder) == 'function'
        and type(backend.makefolder) == 'function'
        and type(backend.listfiles) == 'function'
    local self = {
        Folder = folder,
        Backend = backend,
        Memory = {},
        Persistent = disk,
        Mode = disk and 'local files' or 'session memory',
    }
    local function key(name)
        assert(
            type(name) == 'string' and name:match('^[%w _%-]+$') and #name <= 64,
            'Use 1–64 letters, numbers, spaces, - or _'
        )
        return folder .. '/' .. name .. '.json'
    end
    function self:Write(name, data)
        local path = key(name)
        assert(type(data) == 'string', 'Expected JSON string')
        if disk then
            local ok, err = pcall(function()
                local current = ''
                for part in folder:gmatch('[^/]+') do
                    current = current == '' and part or current .. '/' .. part
                    if not backend.isfolder(current) then
                        backend.makefolder(current)
                    end
                end
                backend.writefile(path, data)
                assert(backend.isfile(path) and backend.readfile(path) == data, 'File verification failed')
            end)
            if not ok then
                return false, tostring(err)
            end
        end
        self.Memory[name] = data
        return true
    end
    function self:Read(name)
        local path = key(name)
        if disk then
            local ok, data = pcall(function()
                if backend.isfile(path) then
                    return backend.readfile(path)
                end
            end)
            if not ok then
                return nil, tostring(data)
            end
            return data
        end
        return self.Memory[name]
    end
    function self:List()
        local names = {}
        if disk then
            local ok, files = pcall(function()
                return backend.isfolder(folder) and backend.listfiles(folder) or {}
            end)
            if not ok then
                return {}, tostring(files)
            end
            for _, path in ipairs(files) do
                local name = path:gsub('\\', '/'):match('/([%w _%-]+)%.json$')
                    or path:match('^([%w _%-]+)%.json$')
                if name and not name:match('^__') then
                    names[name] = true
                end
            end
        else
            for name in pairs(self.Memory) do
                if not name:match('^__') then
                    names[name] = true
                end
            end
        end
        local result = {}
        for name in pairs(names) do
            table.insert(result, name)
        end
        table.sort(result)
        return result
    end
    function self:Delete(name)
        local path = key(name)
        if disk then
            if type(backend.delfile) ~= 'function' then
                return false, 'This environment does not support deleting files'
            end
            local ok, err = pcall(function()
                if backend.isfile(path) then
                    backend.delfile(path)
                end
            end)
            if not ok then
                return false, tostring(err)
            end
        end
        self.Memory[name] = nil
        return true
    end
    return self
end
return Storage

end
factories['ThemeManager'] = function()
local Storage = get('Storage')
local Http = game:GetService('HttpService')
local ThemeManager = {}
function ThemeManager.new(library)
    local self = { Library = library, Storage = Storage.new('MintProject/themes'), Current = 'Mint' }
    local presets = { Mint = '74E3AE', Ice = '82C7F0', Amber = 'EDBD74', Rose = 'E7899D', Violet = 'B7A3EF' }
    function self:SetLibrary(value)
        self.Library = value
        return self
    end
    function self:SetFolder(folder)
        self.Storage = Storage.new(folder .. '/themes')
        return self
    end
    function self:GetThemes()
        local names = {}
        for name in pairs(presets) do
            table.insert(names, name)
        end
        for _, name in ipairs(self.Storage:List()) do
            if not presets[name] then
                table.insert(names, name)
            end
        end
        table.sort(names)
        return names
    end
    function self:ApplyTheme(name)
        if type(name) ~= 'string' or not name:match('^[%w _%-]+$') or #name > 64 then
            return false, 'Select a theme first'
        end
        assert(self.Library, 'SetLibrary first')
        local patch = {}
        if presets[name] then
            for role, color in pairs(self.Library.DefaultTheme) do
                patch[role] = color
            end
            patch.Accent = Color3.fromHex(presets[name])
        else
            local json, err = self.Storage:Read(name)
            if not json then
                return false, err or 'Theme not found'
            end
            local ok, data = pcall(Http.JSONDecode, Http, json)
            if not ok or type(data) ~= 'table' then
                return false, 'Invalid theme'
            end
            for role, hex in pairs(data) do
                if self.Library.DefaultTheme[role] then
                    if type(hex) ~= 'string' or #hex ~= 6 or not hex:match('^%x+$') then
                        return false, 'Invalid theme color'
                    end
                    patch[role] = Color3.fromHex(hex)
                end
            end
        end
        self.Library:SetTheme(patch)
        self.Current = name
        for role, control in pairs(self.ColorControls or {}) do
            control:Set(self.Library.Theme[role], true)
        end
        return true
    end
    function self:SaveCustomTheme(name)
        if type(name) ~= 'string' or not name:match('^[%w _%-]+$') or #name > 64 or presets[name] then
            return false, 'Choose a new custom theme name'
        end
        local values = {}
        for role, color in pairs(self.Library.Theme) do
            values[role] = color:ToHex()
        end
        return self.Storage:Write(name, Http:JSONEncode(values))
    end
    function self:DeleteCustomTheme(name)
        if type(name) ~= 'string' or not name:match('^[%w _%-]+$') or #name > 64 then
            return false, 'Select a theme first'
        end
        if presets[name] then
            return false, 'Built-in themes cannot be deleted'
        end
        return self.Storage:Delete(name)
    end
    function self:ApplyToTab(tab)
        assert(self.Library, 'SetLibrary first')
        local group = tab:AddLeftGroupbox('Theme')
        local selection = group:AddDropdown('__theme.preset', {
            Text = 'Theme',
            Values = self:GetThemes(),
            Default = 'Mint',
            Callback = function(name)
                local ok, err = self:ApplyTheme(name)
                if not ok then
                    self.Library:Notify(err)
                end
            end,
        })
        local name = group:AddInput('__theme.name', { Text = 'Name', Default = 'Custom' })
        local function refresh()
            selection:SetValues(self:GetThemes())
        end
        group:AddButton({
            Text = 'Save theme',
            Func = function()
                local ok, err = self:SaveCustomTheme(name:Get())
                if ok then
                    refresh()
                end
                self.Library:Notify(ok and 'Theme saved' or err)
            end,
        })
        group:AddButton({
            Text = 'Delete theme',
            Func = function()
                local ok, err = self:DeleteCustomTheme(selection:Get())
                if ok then
                    refresh()
                end
                self.Library:Notify(ok and 'Theme deleted' or err)
            end,
        })
        local colors = tab:AddRightGroupbox('Colors')
        self.ColorControls = {}
        for _, role in ipairs({
            'Accent',
            'Background',
            'Panel',
            'Field',
            'Border',
            'Text',
            'Hover',
        }) do
            self.ColorControls[role] = colors:AddLabel(role):AddColorPicker('__theme.color.' .. role, {
                Default = self.Library.Theme[role],
                ThemeRole = role,
                Callback = function(color)
                    self.Library:SetTheme({ [role] = color })
                end,
            })
        end
        return group
    end
    return self
end
return ThemeManager

end
factories['SaveManager'] = function()
local Storage = get('Storage')
local Http = game:GetService('HttpService')
local SaveManager = {}
function SaveManager.new(library)
    local self =
        { Library = library, Storage = Storage.new('MintProject/configs'), Ignore = {}, IgnoreTheme = true }
